function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const { z } = require("zod");
const schema = z.discriminatedUnion("type", [z.object({ type: z.literal("fruit") }), z.object({ type: z.literal("vegetable") })]);
const r = schema.safeParse({ type: "hi" });
if (r.success || !r.error || !Array.isArray(r.error.issues)) broken("parse of a bad discriminator did not fail with issues");
const issue = r.error.issues.find((i) => i.code === "invalid_union" && i.discriminator === "type");
if (!issue) broken("no invalid_union issue with discriminator type: " + JSON.stringify(r.error.issues));
if (!("options" in issue)) symptom("invalid_union issue for a bad discriminator has no options field");
const got = Array.isArray(issue.options) ? issue.options.slice().sort().join(",") : String(issue.options);
if (got !== "fruit,vegetable") broken("options was " + JSON.stringify(issue.options));
console.log("OK: invalid_union issue lists options " + JSON.stringify(issue.options));

